PRODUCTS=[
 dict(slug='rider-intake',name='Rider Intake',job='Turn a signed rider into a list the crew can check.',short='Extract equipment, stage and staffing requests with a reference to the original passage.',title='Every line has a source.',owner='Advance coordinator',input='Signed tour rider and its revision history',output='A reviewable list of requirements',steps=[('Read the signed version','Identify the current rider, revision date and tour contact. Keep the approved original available to the reviewer.'),('Extract the requests','The proposed document model identifies fixture types, dimensions, staff calls and timing. Each extracted line carries a passage and page reference.'),('Resolve ambiguous wording','Send an unclear requirement back to the production manager. A missing unit or quantity stays visible when the requirement moves into Venue Fit.')],faq=('What happens when the rider changes?','Retain the earlier source version. Recheck affected lines against the new signed passage before carrying them into a stop.')),
 dict(slug='venue-fit',name='Venue Fit',job='Find the exception at each stop.',short='Compare the rider with venue plans and approved inventory. Put uncertain matches in the review queue.',title='Put the two sources side by side.',owner='Venue technical lead',input='Reviewed rider lines, venue plan and dated inventory',output='A stop-specific exception record',steps=[('Find the local gap','The fictional Meridian Hall inventory has no Astra 40 profile. Two local alternatives are listed for the technical lead.'),('Check the evidence','Luma P4 has a signed comparison note. Arc P3 still needs supporting documentation. The proposed AI finding points back to the dated sources.'),('Record the decision','Inez Park can approve the documented substitution in the preview. The clear-width question stays open pending an on-site measurement.')],faq=('Who decides whether equipment fits?','The named technical lead owns the decision. The proposed system links evidence and records the outcome. Equipment, staffing, power, rigging and physical setup need qualified staff review.')),
 dict(slug='changeover-planner',name='Changeover Planner',job='Give each handoff a time and an owner.',short='Arrange crew calls and equipment moves between sets around the changes the team has reviewed.',title='Make the next changeover legible.',owner='Tour producer and house crew chief',input='Show schedule, crew availability and reviewed changes',output='A proposed sequence for crew review',steps=[('Start with the running order','Bring the set order, access windows and named department leads into one working sequence.'),('Place the dependencies','Link each proposed equipment move to the decision that supports it. An unresolved stage-width check flags the dependent handoff.'),('Review the call','The crew chief checks actual staffing and local conditions. Record a confirmed sequence or leave the affected cue open.')],faq=('Can an open item enter the schedule?','It can appear as an explicit dependency. A crew lead confirms the affected call after the outstanding evidence arrives.')),
 dict(slug='advance-packet',name='Advance Packet',job='Send the room its reviewed advance.',short='Assemble the agreed layout, crew sequence, approved substitutions and open items for one venue.',title='The handoff keeps the exceptions.',owner='Production advance coordinator',input='Reviewed fit records, stage layout and crew schedule',output='A versioned, venue-specific advance packet',steps=[('Choose the stop','Assemble the rider, venue revisions, reviewed equipment decisions and the latest crew sequence for one show.'),('Separate ready from open','Place each approved substitution beside the reviewer and source. Keep unresolved layout or staffing items in a named follow-up list.'),('Issue the record','Record the revision and export status. The demo JSON preserves both the decision and the open case for a later comparison.')],faq=('What travels with an open item?','The source references, assigned reviewer, missing evidence and next action stay with the packet so the receiving crew can follow up.'))]
